// Every kind of receipt the pull request body can name, judged with real signed receipts and the code CI uses.
test('through the command, a receipt is renewed unless it verifies for this head; forged, foreign, expired, unenrolled and missing ones never stand', async t => {
  const {state, config, calls, runtime, refresh} = signedFixture(t);
  await pullRepository(async f => {
    const requestFile = request(f.root);
    const first = await main(['review', '--directory', f.work, '--base', 'origin/main', '--request-file', requestFile, '--harness', 'claude'], runtime(f));
    assert.equal(first.decision, 'auto_approve');
    const bundle = JSON.parse(fs.readFileSync(first.receipt, 'utf8'));
    const identityFile = path.join(state, `${bundle.payload.key_id}.json`);
    const {private_key: privateKey, id, issuer} = JSON.parse(fs.readFileSync(identityFile, 'utf8'));
    const sign = (payload, key = privateKey) => ({payload, signature: crypto.sign(null, Buffer.from(`clouseau.local-review.v1\0${digest(payload)}`),
      crypto.createPrivateKey(key)).toString('base64url')});
    const alter = (mutate, key) => {
      const payload = structuredClone(bundle.payload); mutate(payload); payload.record_digest = digest(payload.record); return sign(payload, key);
    };
    const plant = files => {
      const entries = Object.entries(files).map(([name, text]) => `100644 blob ${git(f.work, ['hash-object', '-w', '--stdin'], text).trim()}\t${name}\n`).join('');
      const tree = git(f.work, ['mktree'], entries).trim();
      const commit = git(f.work, ['-c', 'user.name=T', '-c', 'user.email=t@example.invalid', 'commit-tree', tree], 'planted\n').trim();
      git(f.work, ['push', '-q', 'origin', `${commit}:refs/tags/planted/${commit}`]);
      return commit;
    };
    const named = other => plant({'clouseau-review.json': JSON.stringify(other) + '\n'});
    const asked = () => ({directory: f.work, base: 'origin/main', repo: REPO, execute: f.execute, installed,
      pull: {number: 7, author: 'fixture-author', head: f.head(), base_sha: git(f.bare, ['rev-parse', 'refs/heads/main']).trim(), body: f.pull.body}});
    const judge = async (body, given = asked) => {f.pull.body = body; return receiptStanding({...given(), pull: {...given().pull, body}});};
    const published = await main(['publish', '--directory', f.work, '--receipt', first.receipt], runtime(f));
    const marker = (commit = published.artifact_commit) => `Body.\n\n<!-- clouseau-local-review:v1 ${commit} -->\n`;
    // The same review, signed by the enrolled key two hours ago for one hour: published, it is what an author finds after the expiry.
    const expired = issueReceipt({record: bundle.payload.record, privateKey, keyId: id, issuer, reviewerSha: bundle.payload.reviewer_sha,
      reviewerDigest: bundle.payload.reviewer_digest, reviewerSemantics: bundle.payload.reviewer_semantics, now: Date.now() - 7200000, lifetime: 3600});
    assert.ok(expired.payload.expires_at < Date.now() / 1000);
    const stale = named(expired);
    // The receipt the author published stands, and nothing else about the pull request is consulted.
    assert.deepEqual(await judge(marker()), {applicable: true, usable: true});
    // Forged, foreign or not-yet-trusted receipts: each is unusable, with CI's own cause class, and none is accepted.
    const foreignKey = crypto.generateKeyPairSync('ed25519').privateKey.export({type: 'pkcs8', format: 'pem'});
    const cases = [
      ['no marker', 'Body without a marker.\n', 'receipt_absent'],
      ['two markers', marker() + marker(), 'receipt_malformed'],
      ['a marker naming a commit that does not exist', marker('a'.repeat(40)), 'receipt_unavailable'],
      ['a commit that holds no receipt', marker(plant({'README.md': 'not a receipt\n'})), 'receipt_unavailable'],
      ['a file that is not JSON', marker(plant({'clouseau-review.json': 'not json\n'})), 'receipt_malformed'],
      ['an envelope with extra fields', marker(named({...bundle, extra: true})), 'receipt_malformed'],
      ['a receipt signed by a key that is not enrolled', marker(named(alter(() => {}, foreignKey))), 'receipt_signature'],
      ['an altered receipt under the old signature', marker(named({...bundle, payload: {...bundle.payload, nonce: 'f'.repeat(64)}})), 'receipt_signature'],
      ['a receipt of another head', marker(named(alter(payload => {payload.record.snapshot.head_sha = 'c'.repeat(40);}))), 'receipt_revision_head'],
      ['a receipt of another repository', marker(named(alter(payload => {payload.record.snapshot.repository = 'someone/else';}))), 'receipt_revision_repository'],
      ['a receipt of another base', marker(named(alter(payload => {payload.record.snapshot.base_sha = 'd'.repeat(40);}))), 'receipt_revision_base'],
      ['a receipt signed for another author', marker(named(alter(payload => {payload.attestation = {author: 'someone', number: 7, signer: 'fixture-author'};}))), 'receipt_attestation'],
      ['an expired receipt', marker(stale), 'receipt_expired'],
    ];
    for (const [name, body, cause] of cases) {
      const standing = await judge(body);
      assert.deepEqual({usable: standing.usable, cause: standing.cause}, {usable: false, cause}, name);
      assert.equal(standing.applicable, true, name); assert.equal(typeof standing.sentence, 'string', name);
    }
    // The engine running here is not the one that signed it, and does not accept that engine's receipts.
    const other = await receiptStanding({...asked(), pull: {...asked().pull, body: marker()}, installed: () => ({sha: 'd'.repeat(40), digest: 'd'.repeat(64), clean: true})});
    assert.equal(other.cause, 'receipt_engine');
    // A failure that is not the receipt's own (GitHub unreachable) is not a verdict: nothing is renewed on a guess.
    await assert.rejects(receiptStanding({...asked(), pull: {...asked().pull, body: marker()}, execute: () => {throw Object.assign(new Error('unreachable'), {stderr: 'gh: Server Error (HTTP 500)'});}}), /unreachable/);
    // Without receipts in the protected configuration (no configuration at all, or none for local review) there is nothing to judge.
    const tree = entries => git(f.work, ['mktree'], entries).trim();
    const commitOf = root => git(f.work, ['-c', 'user.name=T', '-c', 'user.email=t@example.invalid', 'commit-tree', root], 'base\n').trim();
    const withConfig = text => commitOf(tree(`040000 tree ${tree(`100644 blob ${git(f.work, ['hash-object', '-w', '--stdin'], text).trim()}\tclouseau.json\n`)}\t.github\n`));
    const {local_review: dropped, ...withoutReceipts} = config;
    assert.ok(dropped);
    for (const base of [commitOf(tree('')), withConfig(JSON.stringify(withoutReceipts))]) {
      assert.deepEqual(await receiptStanding({...asked(), base, pull: {...asked().pull, body: marker()}}), {applicable: false});
    }

    // The same, through the command: a receipt that stands is up to date, and the reviewer is not asked.
    f.pull.body = marker();
    const asks = calls.length;
    const stands = await refresh(f, {request: requestFile});
    assert.equal(stands.status, 'up_to_date'); assert.match(stands.note, /receipt still verifies/); assert.equal(calls.length, asks);
    // A forged marker is never taken for a receipt: the review is repeated for this head, a receipt is published, the marker replaced, the branch not pushed.
    const before = f.head(); const forged = marker('a'.repeat(40)); f.pull.body = forged;
    const [renewed] = await quiet(() => refresh(f, {request: requestFile}));
    assert.equal(renewed.status, 'renewed'); assert.equal(renewed.pushed, false); assert.equal(renewed.cause, 'receipt_unavailable');
    assert.equal(f.head(), before); assert.equal(f.remoteHead(), before);
    assert.ok(f.pull.body.includes(renewed.marker) && !f.pull.body.includes('a'.repeat(40)), 'the forged marker was replaced');
    assert.equal(f.pull.body.match(/clouseau-local-review:/g).length, 1);
    assert.ok(git(f.bare, ['cat-file', '-t', renewed.artifact_commit]).includes('commit') && renewed.decision === 'auto_approve');
    // The renewed receipt now stands, so asking again does nothing.
    assert.equal((await refresh(f, {request: requestFile})).status, 'up_to_date');

    // The real case: the receipt in the body (and the one this input cached) expired. The same input is reviewed again, taking the
    // remembered answers, a fresh receipt replaces the marker, and the branch on GitHub is not touched.
    f.pull.body = marker(stale);
    const caches = fs.readdirSync(path.join(state, 'reviews'));
    const cacheDirectory = path.join(state, 'reviews', caches.find(name => fs.existsSync(path.join(state, 'reviews', name, 'receipt.json')) &&
      JSON.parse(fs.readFileSync(path.join(state, 'reviews', name, 'receipt.json'))).payload.nonce === bundle.payload.nonce));
    fs.writeFileSync(path.join(cacheDirectory, 'receipt.json'), JSON.stringify(expired) + '\n');
    const reviewed = calls.length;
    const [again, lines] = await quiet(() => refresh(f, {request: requestFile}));
    assert.equal(again.status, 'renewed'); assert.equal(again.cause, 'receipt_expired'); assert.match(lines.join(''), /\(cause: receipt_expired\): it is expired or not yet valid \(it expires `\d{4}-/);
    assert.equal(again.harness_invocations, 0); assert.ok(again.reused_calls >= 2); assert.equal(calls.length, reviewed, 'the remembered answers were used');
    assert.equal(f.head(), before); assert.equal(f.remoteHead(), before); assert.ok(f.pull.body.includes(again.marker) && !f.pull.body.includes(stale));
    assert.notEqual(JSON.parse(fs.readFileSync(again.receipt, 'utf8')).payload.nonce, bundle.payload.nonce);
    assert.equal((await refresh(f, {request: requestFile})).status, 'up_to_date');
    // A tag is never overwritten: publishing a receipt whose nonce names an artifact with other content is refused.
    const squatted = JSON.parse(fs.readFileSync(again.receipt, 'utf8')); const squatter = plant({'clouseau-review.json': 'other\n'});
    git(f.work, ['push', '-q', 'origin', `${squatter}:refs/tags/clouseau-review/${'f'.repeat(64)}`]);
    const resigned = sign({...squatted.payload, nonce: 'f'.repeat(64)});
    const resignedFile = path.join(f.root, 'resigned.json'); fs.writeFileSync(resignedFile, JSON.stringify(resigned));
    await assert.rejects(main(['publish', '--directory', f.work, '--receipt', resignedFile], runtime(f)), /already exists with other content; nothing was published/);
    assert.ok(fs.existsSync(path.join(cacheDirectory, 'request.txt')), 'the stored requirement stayed with the retired evidence');
  }, {ciConfig: config});
});

'use strict';
// A signed local receipt may attest the repository's whole declared verification.
//
// Local side: `evaluate` runs after the recipe's commands and refuses (throws) unless EVERY declared command ran and passed on the exact
// head, native coverage was observed in this run, and the coverage gate CI would enforce (exact, changed_lines or declared) passes.
// Only then does the signed verification record carry `attestation`. A review that cannot attest is never signed.
//
// CI side: `receiptAttests` answers whether the pull request's receipt is fully valid (signature, head, base, engine, expiry, sources)
// AND carries that attestation. Any other answer is false and the repository's own verification runs exactly as before.
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const cp = require('node:child_process');

const VERSION = 1;
const GATE_MODES = ['exact', 'changed_lines', 'declared'];

const describe = command => {
  const text = command.argv.join(' ');
  const shown = text.length > 120 ? `${text.slice(0, 117)}...` : text;
  if (command.error) return `${shown} could not run (${command.error.code || command.error.message}); install the tool it needs`;
  if (command.signal) return `${shown} was stopped by ${command.signal}`;
  if (command.exit_code === null) return `${shown} did not exit`;
  return `${shown} exited ${command.exit_code}`;
};

// The attestation of a verification record, or null. A record attests only when it says so AND its own facts agree.
function attestationOf(technical) {
  const claim = technical?.attestation;
  const ok = claim && claim.version === VERSION && GATE_MODES.includes(claim.coverage_mode) && claim.gate === 'passed' &&
    Array.isArray(technical.commands) && technical.commands.length > 0 && claim.commands === technical.commands.length &&
    technical.verification_status === 'passed' && technical.commands.every(command => command.exit_code === 0 && !command.error && !command.signal) &&
    technical.coverage?.status !== 'unavailable' && technical.coverage?.artifact_freshness === 'observed_current_run' &&
    typeof technical.local_config_digest === 'string' && claim.recipe === technical.local_config_digest;
  return ok ? claim : null;
}

// Baseline totals of the base revision, measured the way the CI job measures them: the same recipe on a clean checkout of the base.
function withBaseline({directory, baseSha, config, parts, verify, exec, gate}, use) {
  const temporary = fs.mkdtempSync(path.join(os.tmpdir(), 'clouseau-base-'));
  const tree = path.join(temporary, 'tree');
  exec('git', ['-C', directory, 'worktree', 'add', '--detach', tree, baseSha], {stdio: 'pipe'});
  try {
    const result = verify({directory: tree, config});
    if (result.verification_status !== 'passed') {
      throw new Error(`the base revision's own verification failed (${result.commands.filter(item => item.exit_code !== 0 || item.error).map(describe).join('; ')}), so no coverage baseline exists`);
    }
    const file = path.join(temporary, 'baseline.json');
    fs.writeFileSync(file, JSON.stringify(gate.measurePlan(parts, tree).totals));
    return use(file);
  } finally {
    try {exec('git', ['-C', directory, 'worktree', 'remove', '--force', tree], {stdio: 'pipe'});} catch { /* the temporary directory is removed next */ }
    fs.rmSync(temporary, {recursive: true, force: true});
  }
}

// Returns `technical` with its attestation, or throws naming exactly why a signature must not be issued.
function evaluate({directory, config, technical, ciConfig, baseSha, verify, exec = cp.execFileSync}) {
  const refuse = problems => {throw new Error(`Local verification is not complete on this head, so no receipt is signed: ${problems.join('; ')}`);};
  const failed = technical.commands.filter(command => command.exit_code !== 0 || command.error || command.signal);
  if (failed.length) refuse(failed.map(describe));
  if (technical.coverage.status === 'unavailable') refuse([`native coverage is unavailable (${technical.coverage.error || 'no report'}); install the coverage tool the recipe needs`]);
  if (technical.coverage.artifact_freshness !== 'observed_current_run') refuse(['the coverage report was not produced by this run']);
  const gate = require('./coverage-gate.cjs');
  const changed = require('./coverage-changed.cjs');
  const mode = changed.modeOf(ciConfig);
  try {
    if (mode === 'exact') {
      if (!technical.coverage.passed) throw new Error('line and branch coverage is not exactly 100%');
    } else {
      const parts = require('./coverage-plan.cjs').coverageParts(config);
      if (mode === 'declared') gate.declaredPlan(parts, directory, baseSha);
      else withBaseline({directory, baseSha, config, parts, verify, exec, gate}, file => gate.changedPlan(parts, directory, baseSha, file));
    }
  } catch (error) {
    refuse([`the ${mode} coverage gate fails: ${error.message}`]);
  }
  return {...technical, attestation: {version: VERSION, recipe: technical.local_config_digest, commands: technical.commands.length,
    coverage_mode: mode, gate: 'passed'}};
}

// CI: does this pull request carry a receipt that is valid in every respect and attests verification? Never throws on a
// receipt that does not verify; that is simply `false` (the repository then runs its checks itself).
async function receiptAttests({github, repo, pr, config, engine}) {
  if (!config.local_review) return false;
  const receipts = require('./local-receipt.cjs');
  const {digest} = require('./acceptance.cjs');
  const {policyDigest} = require('./acceptance-controller.cjs');
  const screened = await receipts.screenReceipt({github, repo, pr, engine, trust: config.local_review, configDigest: digest(config), policyDigest: policyDigest()});
  if (!screened.ref) return false;
  const files = await github.paginate(github.rest.pulls.listFiles, {...repo, pull_number: pr.number, per_page: 100});
  const rejected = await receipts.screenSources({github, repo, pr, snapshot: screened.verified.record.snapshot, config, files,
    reviewerSha: screened.bundle.payload.reviewer_sha});
  if (rejected) return false;
  const {sources} = screened.verified.record.snapshot;
  // The attested recipe must be the accepted base's own `.clouseau-local.json`, which screenSources bound to the base revision.
  const recipe = Object.values(sources).find(item => item.path === '.clouseau-local.json' && item.ref === pr.base.sha);
  let technical = null;
  let accepted = null;
  try {
    technical = JSON.parse(sources.verification.content);
    accepted = digest(JSON.parse(recipe.content));
  } catch { return false; }
  return attestationOf(technical) !== null && technical.local_config_digest === accepted;
}

// The decision the `attested` action operation publishes for a workflow's `if:` conditions.
async function decide({github, context, config, engine}) {
  const number = context.payload.pull_request?.number;
  if (!Number.isInteger(number)) throw new Error('A pull request context is required');
  const {data: pr} = await require('./pull-read.cjs').readPull(github, context.repo, number);
  if (pr.state !== 'open' || pr.draft || pr.base.ref !== config.base_branch) return false;
  return receiptAttests({github, repo: context.repo, pr, config, engine});
}

module.exports = {VERSION, GATE_MODES, attestationOf, evaluate, receiptAttests, decide};

'use strict';

const {test} = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const attestation = require('./verification-attestation.cjs');
const gate = require('./coverage-gate.cjs');
const receipts = require('./local-receipt.cjs');
const {digest} = require('./acceptance.cjs');

const BASE = 'b'.repeat(40);
const HEAD = 'a'.repeat(40);
const recipe = {version: 2, base_branch: 'main', readme: 'README.md', repository_policy: 'AGENTS.md', verification: [['run', 'tests']],
  coverage: [{format: 'lcov', report: 'cov/lcov.info', source_directory: 'src', source_suffixes: ['.rs']}]};
const command = (extra = {}) => ({argv: ['run', 'tests'], exit_code: 0, ...extra});
const technical = (extra = {}) => ({commands: [command()], verification_status: 'passed', local_config_digest: digest(recipe),
  coverage: {status: 'exact', passed: true, artifact_freshness: 'observed_current_run'}, ...extra});
const attested = (mode = 'exact', extra = {}) => ({...technical(), attestation: {version: 1, recipe: digest(recipe), commands: 1, coverage_mode: mode, gate: 'passed', ...extra}});

test('a record attests only when it says so and its own facts agree', () => {
  assert.ok(attestation.attestationOf(attested()));
  assert.equal(attestation.attestationOf(null), null);
  assert.equal(attestation.attestationOf(technical()), null);
  for (const mutate of [
    t => {t.attestation.version = 2;}, t => {t.attestation.coverage_mode = 'other';}, t => {t.attestation.gate = 'failed';},
    t => {t.commands = [];}, t => {t.attestation.commands = 2;}, t => {t.verification_status = 'failed';},
    t => {t.commands[0].exit_code = 1;}, t => {t.commands[0].error = {code: 'ENOENT'};}, t => {t.commands[0].signal = 'SIGTERM';},
    t => {t.coverage.status = 'unavailable';}, t => {t.coverage.artifact_freshness = 'unverified';},
    t => {delete t.coverage;}, t => {t.attestation.recipe = 'y';},
  ]) {
    const value = attested(); mutate(value);
    assert.equal(attestation.attestationOf(value), null, JSON.stringify(mutate.toString()));
  }
});

const refused = (value, pattern, options = {}) => assert.throws(() => attestation.evaluate({directory: '/x', config: recipe, ciConfig: {}, baseSha: BASE, verify: () => {}, ...options, technical: value}),
  error => pattern.test(error.message) && /no receipt is signed/.test(error.message));

test('a signature is refused unless every declared command ran and passed', () => {
  refused(technical({commands: [command({exit_code: null, error: {code: 'ENOENT', message: 'spawn'}})]}), /run tests could not run \(ENOENT\); install the tool/);
  refused(technical({commands: [command({exit_code: null, error: {message: 'odd'}})]}), /could not run \(odd\)/);
  refused(technical({commands: [command({exit_code: null, signal: 'SIGTERM'})]}), /stopped by SIGTERM/);
  refused(technical({commands: [command({exit_code: null})]}), /did not exit/);
  refused(technical({commands: [command(), command({argv: ['x'.repeat(200)], exit_code: 2})]}), /x{117}\.\.\. exited 2/);
});

test('a signature is refused without observed native coverage', () => {
  refused(technical({coverage: {status: 'unavailable', error: 'ENOENT', artifact_freshness: 'unverified'}}), /coverage is unavailable \(ENOENT\)/);
  refused(technical({coverage: {status: 'unavailable', artifact_freshness: 'unverified'}}), /unavailable \(no report\)/);
  refused(technical({coverage: {status: 'exact', passed: true, artifact_freshness: 'unverified'}}), /not produced by this run/);
});

test('exact mode needs exactly full coverage', () => {
  const result = attestation.evaluate({directory: '/x', config: recipe, technical: technical(), ciConfig: null, baseSha: BASE});
  assert.deepEqual(result.attestation, {version: 1, recipe: digest(recipe), commands: 1, coverage_mode: 'exact', gate: 'passed'});
  assert.ok(attestation.attestationOf(result));
  refused(technical({coverage: {status: 'below_threshold', passed: false, artifact_freshness: 'observed_current_run'}}), /exact coverage gate fails: line and branch coverage is not exactly 100%/);
});

test('changed_lines measures the base revision in a clean worktree and removes it', t => {
  const calls = [];
  const exec = (name, args) => {calls.push(args.slice(2).join(' ').replace(/ \S+clouseau-base-\S+/, ' TREE'));};
  const verified = [];
  t.mock.method(gate, 'measurePlan', () => ({totals: {lines: [4, 4], branches: [2, 2]}}));
  let baseline;
  t.mock.method(gate, 'changedPlan', (parts, directory, base, file) => {baseline = JSON.parse(fs.readFileSync(file, 'utf8')); assert.equal(base, BASE); assert.equal(directory, '/x');});
  const verify = options => {verified.push(options.directory); return {verification_status: 'passed', commands: []};};
  const result = attestation.evaluate({directory: '/x', config: recipe, technical: technical(), ciConfig: {coverage: {mode: 'changed_lines'}}, baseSha: BASE, verify, exec});
  assert.equal(result.attestation.coverage_mode, 'changed_lines');
  assert.deepEqual(baseline, {lines: [4, 4], branches: [2, 2]});
  assert.match(verified[0], /clouseau-base-.*tree$/);
  assert.deepEqual(calls.map(call => call.split(' ')[0]), ['worktree', 'worktree']);
  assert.ok(!fs.existsSync(verified[0]));
});

test('changed_lines refuses a changed line left uncovered, a failing base and a worktree that cannot be removed', t => {
  t.mock.method(gate, 'measurePlan', () => ({totals: {lines: [1, 1], branches: [0, 0]}}));
  t.mock.method(gate, 'changedPlan', () => {throw new Error('lines: 1 changed uncovered');});
  const ok = () => ({verification_status: 'passed', commands: []});
  const ciConfig = {coverage: {mode: 'changed_lines'}};
  refused(technical(), /changed_lines coverage gate fails: lines: 1 changed uncovered/, {ciConfig, verify: ok, exec: (name, args) => {if (args[3] === 'remove') throw new Error('cannot remove');}});
  refused(technical(), /base revision's own verification failed \(run tests exited 1; run tests could not run \(ENOENT\)/, {ciConfig, exec() {},
    verify: () => ({verification_status: 'failed', commands: [command({exit_code: 1}), command({exit_code: null, error: {code: 'ENOENT'}}), command()]})});
});

test('declared mode is held to the minimums at the base revision', t => {
  const seen = [];
  t.mock.method(gate, 'declaredPlan', (parts, directory, base) => {seen.push(base);});
  const result = attestation.evaluate({directory: '/x', config: recipe, technical: technical(), ciConfig: {coverage: {mode: 'declared'}}, baseSha: BASE});
  assert.equal(result.attestation.coverage_mode, 'declared');
  assert.deepEqual(seen, [BASE]);
  t.mock.method(gate, 'declaredPlan', () => {throw new Error('below declared');});
  refused(technical(), /declared coverage gate fails: below declared/, {ciConfig: {coverage: {mode: 'declared'}}});
});

// CI side.
const trust = {mode: 'optional', max_age_seconds: 3600, keys: []};
const config = {base_branch: 'main', local_review: trust};
const pr = {number: 8, state: 'open', draft: false, base: {ref: 'main', sha: BASE}, head: {sha: HEAD}};
const github = (value = pr) => ({paginate: async () => [], rest: {pulls: {get: async () => ({data: value}), listFiles() {}}}});
const source = (value = recipe) => ({path: '.clouseau-local.json', ref: BASE, content: JSON.stringify(value)});
const verified = (sources = {verification: {content: JSON.stringify(attested())}, config: source()}) => ({ref: 'r'.repeat(40), bundle: {payload: {reviewer_sha: 'e'.repeat(40)}}, verified: {record: {snapshot: {sources}}}});
const screen = (t, screened, rejected = null) => {
  t.mock.method(receipts, 'screenReceipt', async () => screened);
  t.mock.method(receipts, 'screenSources', async () => rejected);
};
const run = (value = pr) => attestation.receiptAttests({github: github(value), repo: {owner: 'o', repo: 'r'}, pr: value, config, engine: null});

test('only a fully valid receipt that attests the accepted recipe lets CI skip verification', async t => {
  assert.equal(await attestation.receiptAttests({github: github(), repo: {}, pr, config: {}, engine: null}), false);
  screen(t, {ref: null});
  assert.equal(await run(), false);
  screen(t, verified(), 'source');
  assert.equal(await run(), false);
  screen(t, verified());
  assert.equal(await run(), true);
  const bad = {verification: {content: JSON.stringify(attested())}};
  screen(t, verified(bad)); assert.equal(await run(), false);
  screen(t, verified({...bad, config: {...source(), ref: HEAD}})); assert.equal(await run(), false);
  screen(t, verified({...bad, config: {...source(), content: 'not json'}})); assert.equal(await run(), false);
  screen(t, verified({...bad, config: source({...recipe, verification: [['other']]})})); assert.equal(await run(), false);
  screen(t, verified({verification: {content: '{'}, config: source()})); assert.equal(await run(), false);
  screen(t, verified({verification: {content: JSON.stringify(technical())}, config: source()})); assert.equal(await run(), false);
});

test('the attested operation decides for the pull request in context', async t => {
  screen(t, verified());
  const context = {repo: {owner: 'o', repo: 'r'}, payload: {pull_request: {number: 8}}};
  const decide = (value, ctx = context) => attestation.decide({github: github(value), context: ctx, config, engine: null});
  assert.equal(await decide(pr), true);
  await assert.rejects(decide(pr, {...context, payload: {}}), /pull request context/);
  assert.equal(await decide({...pr, state: 'closed'}), false);
  assert.equal(await decide({...pr, draft: true}), false);
  assert.equal(await decide({...pr, base: {ref: 'other', sha: BASE}}), false);
});

// Policy side: skipped required steps are accepted only on an attestation. The policy suite stays untouched to keep its evidence small.
const {createPolicy} = require('./policy.cjs');
const policyConfig = require('../test/fixtures/config.json');
const PR_REPO = {owner: 'gaulatti', repo: 'colombo'};
const small = {number: 8, head: {sha: HEAD, ref: 'fix/naming', repo: {id: 42}}, base: {sha: BASE, ref: 'main'}};
function ci(stepConclusions) {
  const steps = policyConfig.verification.steps.map((name, index) => ({name, conclusion: stepConclusions[index] ?? 'success'}));
  return {rest: {actions: {
    listWorkflowRuns: async () => ({data: {workflow_runs: [{id: 22, head_sha: HEAD, head_branch: 'fix/naming', head_repository: {id: 42}, pull_requests: [],
      event: 'pull_request', status: 'completed', conclusion: 'success', html_url: 'https://github.com/gaulatti/colombo/actions/runs/22'}]}}),
    listJobsForWorkflowRun: async () => ({data: [{name: policyConfig.verification.job, conclusion: 'success', steps}]}),
  }}, paginate: async (method, options) => (await method(options)).data};
}

test('skipped required steps count only when a valid receipt attests the verification', async () => {
  const seen = [];
  const attesting = answer => createPolicy(policyConfig, {attested: async (github, repository, pull) => {seen.push([repository, pull.number]); return answer;}});
  const skipped = () => ci(policyConfig.verification.steps.map(() => 'skipped'));
  assert.match((await attesting(true).technicalRun(skipped(), PR_REPO, small)).url, /runs\/22/);
  assert.deepEqual(seen, [[PR_REPO, 8]]);
  assert.match((await attesting(false).technicalRun(skipped(), PR_REPO, small)).failure, /Required verification step "[^"]+" concluded skipped/);
  assert.match((await createPolicy(policyConfig).technicalRun(skipped(), PR_REPO, small)).failure, /concluded skipped/);
  // A failed step is never excused by an attestation, and a fully successful job never asks for one.
  assert.match((await attesting(true).technicalRun(ci(['skipped', 'failure']), PR_REPO, small)).failure, /concluded failure/);
  seen.length = 0;
  assert.ok((await attesting(true).technicalRun(ci([]), PR_REPO, small)).url);
  assert.deepEqual(seen, []);
});

test('a version 2 policy asks the receipt verifier whether verification is attested', async t => {
  const calls = [];
  t.mock.method(attestation, 'receiptAttests', async options => {calls.push(options); return true;});
  const policy = createPolicy({...policyConfig, version: 2,
    acceptance: {examiner: 'deepseek-flash', challenger: 'deepseek-v4-pro', grader: 'routed', grading_model: 'deepseek-flash', repair_attempts: 2}}, {engine: null});
  assert.ok((await policy.technicalRun(ci(policyConfig.verification.steps.map(() => 'skipped')), PR_REPO, small)).url);
  assert.equal(calls.length, 1); assert.equal(calls[0].pr, small); assert.equal(calls[0].config.version, 2);
});

